/**
 * Tests for core/generate — the four generated files (decisions 39 / 79 / 87).
 *
 * The behaviours that matter: the head is readable back (that is what the freshness check compares),
 * the tree hash ignores order and ignores writes that cannot change the output, and each file keeps
 * the layout decision 87 pinned down — including the two rules that are easy to get wrong, namely
 * that a blocked issue leaves its status section, and that a pipe in a summary cannot break a row.
 */

import assert from 'node:assert/strict'
import { describe, it } from 'node:test'

import { type Identity, type Issue, type Tag, type Timestamp } from './entity.ts'
import {
  type GeneratedMeta,
  generateAll,
  hashSourceTree,
  readGeneratedHead,
  renderBoardFile,
  renderIndexFile,
  renderLogFile,
  renderTagsIndexFile,
  tagRows,
} from './generate.ts'
import { type Vocab } from './vocab.ts'

const META: GeneratedMeta = Object.freeze({ generatedAt: '2026-10-15T12:00:00Z', sourceTree: 'a'.repeat(64) })

const vocab: Vocab = Object.freeze({
  issueTypes: Object.freeze(['task', 'bug']),
  kbTypes: Object.freeze(['note']),
  priorities: Object.freeze(['S1', 'S2', 'S3']),
  statuses: Object.freeze([
    Object.freeze({ name: 'todo', order: 10 }),
    Object.freeze({ name: 'in_progress', order: 20 }),
    Object.freeze({ name: 'closed', order: 90 }),
    Object.freeze({ name: 'legacy', order: 95, deprecated: true }),
  ]),
  transitions: Object.freeze([]),
  closed: Object.freeze(['closed']),
  resolutions: Object.freeze(['fixed', 'invalid', 'limitation', 'abandoned']),
})

let seq = 0
// The branded key is a compile-time idea; a test fixture is allowed to write it as a string.
const issue = (over: Omit<Partial<Issue>, 'key'> & Readonly<{ key: string }>): Issue => {
  seq += 1
  return Object.freeze({
    project: 'DH',
    issueType: 'task',
    status: 'todo',
    summary: `summary ${String(seq)}`,
    priority: 'S3',
    tags: Object.freeze([]),
    links: Object.freeze([]),
    revision: 1,
    createdAt: '2026-10-15T08:00:00Z' as Timestamp,
    updatedAt: `2026-10-15T08:00:${String(seq).padStart(2, '0')}Z` as Timestamp,
    reporter: 'human:daiqc' as Identity,
    kbRefs: Object.freeze([]),
    conflicted: false,
    body: '',
    ...over,
  } as Issue)
}

describe('generate: the source tree hash (decision 79)', () => {
  it('does not depend on the order the entries arrive in', () => {
    const entries = [
      { path: 'tags/demo.md', sha256: 'b' },
      { path: 'config.md', sha256: 'a' },
    ]
    assert.equal(hashSourceTree(entries), hashSourceTree([...entries].reverse()))
  })

  it('changes when one input changes, and only then', () => {
    const before = hashSourceTree([{ path: 'config.md', sha256: 'a' }])
    assert.equal(hashSourceTree([{ path: 'config.md', sha256: 'a' }]), before)
    assert.notEqual(hashSourceTree([{ path: 'config.md', sha256: 'b' }]), before)
    assert.notEqual(hashSourceTree([{ path: 'config.md', sha256: 'a' }, { path: 'x', sha256: 'b' }]), before)
  })
})

describe('generate: the head (decisions 39/79)', () => {
  it('round-trips through readGeneratedHead, which the freshness check uses', () => {
    const text = renderTagsIndexFile([], META)
    assert.deepEqual(readGeneratedHead(text), META)
  })

  it('refuses a file it did not generate', () => {
    assert.equal(readGeneratedHead('# hand written\n'), undefined)
    assert.equal(readGeneratedHead('<!-- something else -->\n'), undefined)
  })
})

describe('generate: BOARD.md (decision 87)', () => {
  it('sections open statuses in vocabulary order and skips empty ones', () => {
    const board = renderBoardFile(
      [issue({ key: 'DH-2', status: 'in_progress' }), issue({ key: 'DH-1', status: 'todo' })],
      vocab,
      META,
    )
    assert.match(board, /## todo（1）/)
    assert.match(board, /## in_progress（1）/)
    assert.doesNotMatch(board, /## legacy/)
    assert.ok(board.indexOf('## todo') < board.indexOf('## in_progress'), 'order is the column order')
    // Decision 55: the prose around the data is Chinese, and the data itself is untouched.
    assert.ok(board.startsWith('<!-- generated by dsh-jira — do not edit by hand'), 'the head stays English')
    assert.match(board, /^\| key \| summary \| priority \| assignee \| updated \|$/m, 'column names are field names')
  })

  it('sorts a section by priority, S1 first', () => {
    const board = renderBoardFile(
      [issue({ key: 'DH-9', priority: 'S3' }), issue({ key: 'DH-8', priority: 'S1' })],
      vocab,
      META,
    )
    assert.ok(board.indexOf('DH-8') < board.indexOf('DH-9'))
  })

  it('marks a conflicted row', () => {
    const board = renderBoardFile([issue({ key: 'DH-3', conflicted: true })], vocab, META)
    assert.match(board, /\| ⚠️ DH-3 \|/u)
  })

  it('escapes a pipe so a summary cannot break the row', () => {
    const board = renderBoardFile([issue({ key: 'DH-4', summary: 'a | b' })], vocab, META)
    assert.match(board, /a \\\| b/u)
  })

  it('moves a blocked issue out of its status section and into the last one', () => {
    const blocker = issue({ key: 'DH-5', status: 'in_progress' })
    const blocked = issue({ key: 'DH-6', links: [{ type: 'is_blocked_by', target: 'DH-5' as never }] })
    const board = renderBoardFile([blocker, blocked], vocab, META)
    assert.match(board, /## 被阻塞（1）/)
    // Both issues left the `todo` column, so an empty section is not printed at all.
    assert.doesNotMatch(board, /## todo/u)
    // DH-6 appears exactly once — in the blocked table, not twice.
    assert.equal(board.split('DH-6').length - 1, 1)
    assert.ok(board.indexOf('## 被阻塞') > board.indexOf('## in_progress'), 'blocked goes last')
  })

  it('treats an unfindable blocker as blocking, not as ready', () => {
    const board = renderBoardFile(
      [issue({ key: 'DH-7', links: [{ type: 'is_blocked_by', target: 'DH-404' as never }] })],
      vocab,
      META,
    )
    assert.match(board, /## 被阻塞（1）/)
  })

  it('puts a deprecated status in its own section and counts the closed ones', () => {
    const board = renderBoardFile(
      [issue({ key: 'DH-10', status: 'legacy' }), issue({ key: 'DH-11', status: 'closed' })],
      vocab,
      META,
    )
    assert.match(board, /## 已下线状态（1）/)
    assert.match(board, /closed: 1/)
  })
})

describe('generate: index.md, log.md, tags/index.md (decision 87)', () => {
  it('lists projects and knowledge domains, and no individual issue', () => {
    const index = renderIndexFile(
      [{ key: 'DH', name: 'deepseek-harness', open: 3 }],
      [{ name: 'os', entries: 2 }],
      META,
    )
    assert.match(index, /\[DH\]\(\.\/projects\/DH\/\)/)
    assert.match(index, /\| \[DH\]\(\.\/projects\/DH\/\) \| deepseek-harness \| 3 \|/u)
    assert.match(index, /\[os\]\(\.\/knowledge\/os\/\) — 2 条/)
    assert.doesNotMatch(index, /DH-\d/u)
  })

  it('renders keyed commits, and says so when there are none', () => {
    const log = renderLogFile([{ hash: 'abc1234', date: '2026-10-15', subject: 'DH-12: create' }], META)
    assert.match(log, /`abc1234` 2026-10-15 — DH-12: create/)
    assert.match(renderLogFile([], META), /（还没有）/)
  })

  it('renders tags alphabetically with their use count', () => {
    const tags: readonly Tag[] = Object.freeze([
      Object.freeze({ name: 'zeta', description: 'last', aliases: Object.freeze([]) }),
      Object.freeze({ name: 'alpha', description: 'first', aliases: Object.freeze([]) }),
    ])
    const rows = tagRows(tags, [issue({ key: 'DH-20', tags: ['alpha'] })])
    const index = renderTagsIndexFile(rows, META)
    assert.match(index, /`alpha` — first（1 次）/)
    assert.match(index, /`zeta` — last（0 次）/)
    assert.ok(index.indexOf('alpha') < index.indexOf('zeta'))
  })
})

describe('generate: determinism (the freshness assertion depends on it)', () => {
  it('produces byte-identical output for identical input', () => {
    const input = {
      meta: META,
      vocab,
      issues: [issue({ key: 'DH-30' })],
      projects: [{ key: 'DH', name: 'demo', open: 1 }],
      domains: [{ name: 'os', entries: 1 }],
      tags: [{ name: 'demo', description: 'demo tag', uses: 1 }],
      commits: [{ hash: 'abc1234', date: '2026-10-15', subject: 'DH-30: create' }],
    }
    assert.deepEqual(generateAll(input), generateAll(input))
    assert.deepEqual(Object.keys(generateAll(input)).sort(), ['BOARD.md', 'index.md', 'log.md', 'tags/index.md'])
  })
})
